local config = {
  ui_story_32040401_1_dialog_content = "Biarkan saya menghitungnya untuk terakhir kalinya. Satu, dua, tiga... Yap, itu semua!",
  ui_story_32040401_2_dialog_content = "Ada segala macam barang di sini dari seluruh dunia. Illumina, Gurun Rediesel... Bahkan ada barang-barang dari Longzhou di sini!",
  ui_story_32040401_3_dialog_content = "May Saya bertanya untuk apa semua ini, Lady Joshua?",
  ui_story_32040401_4_dialog_content = "Oh, ini baru saja <color=#FFB400>hadiah</color> yang saya ambil selama perjalanan saya.",
  ui_story_32040401_5_dialog_content = "Sejak meninggalkan Lumopolis, saya menemukan banyak hal baru dan menakjubkan.",
  ui_story_32040401_6_dialog_content = "Selama kunjungan baru-baru ini ke Northland, saya belajar betapa terisolasi dan pendiamnya orang-orang di negara ini.",
  ui_story_32040401_7_dialog_content = "Maka, saya mulai mencari cara untuk berbagi pengalaman menarik saya dengan anak-anak.",
  ui_story_32040401_8_dialog_content = "Jadi selama ini Anda mengumpulkan hadiah dari seluruh dunia hanya untuk mereka?",
  ui_story_32040401_9_dialog_content = "Memang. Saya berdoa agar hadiah saya akan membangkitkan keingintahuan masa muda mereka, dan memberi mereka gambaran tentang luasnya dunia kita yang sebenarnya.",
  ui_story_32040401_10_dialog_content = "Di pasir Gurun Rediesel yang tak kenal ampun, sekelompok Aurorian menemukan cara untuk bertahan hidup bersama berdasarkan kesetiaan dan persahabatan.",
  ui_story_32040401_11_dialog_content = "Dan di Federasi Illumina, satu tembok berdiri di antara medan perang yang dilanda perang dan kehidupan yang sederhana namun memuaskan.",
  ui_story_32040401_12_dialog_content = "Di Twin Pavilions Bay, saya bahkan bertemu dengan seorang musafir yang berasal dari Longzhou, sebuah daratan yang terletak jauh di seberang lautan. Budaya dan sejarah mereka sangat berbeda dengan Astra...",
  ui_story_32040401_13_dialog_content = "Jika anak-anak ini dapat memahami betapa besarnya dunia kita, mungkin mereka akan memiliki lebih banyak hal untuk dinantikan dalam hidup ini.",
  ui_story_32040401_14_dialog_content = "Begitu banyak pemikiran yang dimasukkan ke dalam hadiah kecil seperti itu... Anda luar biasa, Nona Joshua!",
  ui_story_32040401_15_dialog_content = "Hahaha, aku tidak akan sejauh itu. Selain itu, ini dapat membantu saya menebus beberapa <color=#FFB400>penyesalan masa laluku</color>.",
  ui_story_32040401_16_dialog_content = "Maaf atas keterlambatannya, Bu Joshua-Hmm? Sungguh mengejutkan melihat Anda di sini juga, PlayerName.",
  ui_story_32040401_17_dialog_content = "Hai, Novio! Jadi kamu orangnya Lady Joshua sedang menunggu!",
  ui_story_32040401_18_dialog_content = "Memang. Tn. Novio dengan murah hati setuju untuk membantu saya mengumpulkan anak-anak, sehingga saya dapat membagikan hadiah mereka.",
  ui_story_32040401_19_dialog_content = "Jangan pikirkan itu.",
  ui_story_32040401_20_dialog_content = "<size=33>Melakukan Novio tahu tentang situasi Anda, Lady Joshua?</size>",
  ui_story_32040401_21_dialog_content = "<size=33>Dia belum menyebutkannya, meskipun aku yakin dia pasti sudah punya ide sekarang.</size>",
  ui_story_32040401_22_dialog_content = "Anak-anak sudah siap dan menunggu, teman-teman. Kami dapat pergi setelah Anda memasukkan hadiah ke kereta.",
  ui_story_32040401_23_dialog_content = "Wow! Begitu banyak hadiah!",
  ui_story_32040401_24_dialog_content = "Apakah ini instrumen dari Longzhou? Aku belum pernah melihat yang seperti ini sebelumnya...",
  ui_story_32040401_25_dialog_content = "Mesin game dari Illumina! Saya ingin yang itu!",
  ui_story_32040401_26_dialog_content = "Tenanglah, anak-anak. Ada banyak hadiah untuk semua orang.",
  ui_story_32040401_27_dialog_content = "Fiuh... Itu jauh lebih melelahkan dari yang kukira. Saya tidak menyangka akan ada begitu banyak anak!",
  ui_story_32040401_28_dialog_content = "Kerja keras Anda sangat dihargai. Bolehkah saya menawarkan Anda minuman?",
  ui_story_32040401_29_dialog_content = "Tentu! Dan sekali lagi terima kasih telah bertahan, Novio. Saya tidak berpikir Nyonya Joshua dan aku bisa menangani semua anak itu tanpa bantuanmu.",
  ui_story_32040401_30_dialog_content = "Kita sama dalam hal itu, bukan? Menurut pemahaman saya, Anda hanya dimaksudkan untuk membantu mengangkut hadiah, namun Anda memilih untuk tetap tinggal dan membantu kami.",
  ui_story_32040401_31_dialog_content = "Ya, saya tidak bisa pergi begitu saja tanpa menawarkan bantuan; dia adalah teman yang baik. Selain itu, itu untuk tujuan yang baik!",
  ui_story_32040401_32_dialog_content = "Tetap saja, aku tidak mengharapkanmu untuk membantu Lady Joshua dengan mempromosikan budaya dari luar Northland.",
  ui_story_32040401_33_dialog_content = "Dia hanya ingin memperkaya kehidupan anak-anak muda kita dengan memperluas wawasan mereka. Motifnya murni, saya yakin itu.",
  ui_story_32040401_34_dialog_content = "Tidak hanya itu... Ratu Bethlehem pernah memiliki seorang kakak perempuan yang menikah dengan mantan gubernur Lumopolis, dan meninggalkan Northland untuk menemaninya.",
  ui_story_32040401_35_dialog_content = "Mantan Gubernur Lumopolis?",
  ui_story_32040401_36_dialog_content = "Mungkin... Atau mungkin yang sebelumnya? Ingatan saya agak kabur. Pada saat itu, saya hanyalah roh gunung, dan saya hampir tidak peduli dengan urusan pemerintahan.",
  ui_story_32040401_37_dialog_content = "Yang kuingat hanyalah raut kesepian di wajahnya saat dia pergi dari istana.",
  ui_story_32040401_38_dialog_content = "Serta... Ekspresi Ratu Bethlehem saat jenazahnya dikirim kembali untuk disemayamkan.",
  ui_story_32040401_39_dialog_content = "Saat itu, aku tidak bisa membantu wanita malang itu, dan sekarang... Ah, tolong maafkan aku. Saya seharusnya tidak menyusahkan Anda dengan hal-hal membosankan di masa lalu.",
  ui_story_32040401_40_dialog_content = "(Jadi rata Novio memiliki bagian penyesalannya sendiri, ya ...)",
  ui_story_32040401_41_dialog_content = "Permisi? Apakah Anda yang membawakan kami semua hadiah ini?",
  ui_story_32040401_42_dialog_content = "Hah? Mengapa ya, kami melakukannya! Jika Anda mau, bicaralah dengan wanita baik berambut putih di sana.",
  ui_story_32040401_43_dialog_content = "Saya tidak ingin hadiah apapun. Aku hanya ingin bertanya padamu.",
  ui_story_32040401_44_dialog_content = "Mengapa Anda bersusah payah membawakan kami hadiah dari dunia luar? Apa untungnya bagi Anda?",
  ui_story_32040401_45_dialog_content = "Dan mengapa Anda membantu mereka, Tuhan Novio? Bukankah kamu mengatakan bahwa Northland adalah surga terakhir yang tersisa untuk Aurorian...?",
  ui_story_32040401_46_dialog_content = "(Oh, pertanyaan yang sangat tajam... apa yang terjadi pada gadis kecil ini?)",
  ui_story_32040401_47_dialog_content = "Ya ampun, jangan ini lagi... Tolong jangan tersinggung, PlayerName.",
  ui_story_32040401_48_dialog_content = "Anak ini bercita-cita menjadi ksatria untuk melindungi seluruh Northland. Dia telah membuktikan dirinya cukup berbakat untuk anak seusianya.",
  ui_story_32040401_49_dialog_content = "Namun, dia masih memiliki ruang untuk tumbuh dalam hal komunikasi interpersonal. Saya minta maaf jika pertanyaannya agak terlalu terus terang.",
  ui_story_32040401_50_dialog_content = "Adapun Anda, anak saya, yakinlah itu PlayerName dan Nyonya Joshua menanggung kita tidak ada niat buruk sedikit pun.",
  ui_story_32040401_51_dialog_content = "Sekarang datang, minta maaf kepada tamu kami.",
  ui_story_32040401_52_dialog_content = "... Maaf.",
  ui_story_32040401_53_dialog_content = "Dengarkan baik-baik, si kecil. Jika Anda benar-benar ingin mempertahankan Northland sebagai ksatria yang melayani ratu, Anda harus belajar memperlakukan orang lain dengan sopan dan penuh pertimbangan.",
  ui_story_32040401_54_dialog_content = "Meskipun kejujuran dan ketulusan Anda terpuji, bersikap terlalu terus terang terkadang dapat menimbulkan lebih banyak masalah, baik untuk diri sendiri maupun orang yang Anda cintai.",
  ui_story_32040401_55_dialog_content = "Jadi maksudmu aku tidak seharusnya mengatakan yang sebenarnya?",
  ui_story_32040401_56_dialog_content = "Tidak nak, bukan itu yang kumaksudkan... Aku memintamu menahan diri untuk tidak memutarbalikkan kata-kataku seperti itu.",
  ui_story_32040401_57_dialog_content = "(Hahaha... Sepertinya ini yang mereka maksud dengan kepolosan seperti anak kecil, ya?)",
  ui_story_32040401_58_dialog_content = "...",
  ui_story_32040401_59_dialog_content = "Saya tidak bermaksud membuat marah Tuhan Novio. Tapi saya tidak mengerti mengapa saya tidak bisa mengatakan apa yang sebenarnya saya pikirkan sepanjang waktu ...",
  ui_story_32040401_60_dialog_content = "Halo sayangku.",
  ui_story_32040401_61_dialog_content = "I-Itu kamu! Apa sebenarnya yang kamu rencanakan ?!",
  ui_story_32040401_62_dialog_content = "<size=33>Tunggu, tidak... Tuhan Novio mengatakan saya harus memperlakukan orang lain dengan sopan.</size>",
  ui_story_32040401_63_dialog_content = "... Terima kasih telah membawakan kami hadiah.",
  ui_story_32040401_64_dialog_content = "Kau tidak perlu berterima kasih padaku, si kecil. Lagi pula, Anda belum mendapatkan hadiah.",
  ui_story_32040401_65_dialog_content = "Dan bukankah itu kebenaran yang ingin Anda bicarakan?",
  ui_story_32040401_66_dialog_content = "Hah? B-Bagaimana kau tahu?!",
  ui_story_32040401_67_dialog_content = "Heehee, itu tertulis di seluruh wajah kecilmu yang menggemaskan.",
  ui_story_32040401_68_dialog_content = "Emm... Y-Yah, aku tidak bisa menahannya! Itu semua karena aku tidak mengerti!",
  ui_story_32040401_69_dialog_content = "Yang mulia Novio mengatakan bahwa Aurorian di luar Northland tidak dapat bersatu di bawah satu tujuan, dan itulah mengapa Eclipsites berkeliaran di seluruh daratan.",
  ui_story_32040401_70_dialog_content = "Tapi orang dewasa itu masih memintamu untuk datang ke sini dan memberitahu kami semua tentang betapa menyenangkannya di luar sana?!",
  ui_story_32040401_71_dialog_content = "B-Bukankah itu berarti dia membiarkanmu menipu kami...?",
  ui_story_32040401_72_dialog_content = "Hmm, ini memang topik yang sangat rumit, tapi untuk anak seusiamu yang bisa mengerti hal ini... Kamu gadis kecil yang luar biasa.",
  ui_story_32040401_73_dialog_content = "...Hah?",
  ui_story_32040401_74_dialog_content = "Yang pasti, tidak ada tempat lain di seluruh Astra yang damai dan sakral seperti Northland.",
  ui_story_32040401_75_dialog_content = "Tetapi orang yang berbeda dari tempat yang berbeda memiliki cara hidup mereka sendiri. Aku hanya ingin kau dan temanmu mengerti itu.",
  ui_story_32040401_76_dialog_content = "Dengan mengetahui hal ini, Anda akan lebih siap untuk menempa masa depan yang lebih cerah bagi diri Anda sendiri.",
  ui_story_32040401_77_dialog_content = "Dan bahkan setelah belajar lebih banyak tentang dunia, tidak apa-apa jika Anda masih mencintai Northland lebih dari tempat lain.",
  ui_story_32040401_78_dialog_content = "Aduh... um...",
  ui_story_32040401_79_dialog_content = "K-Kau tidak hanya memberitahuku apa yang ingin kudengar, kan...?",
  ui_story_32040401_80_dialog_content = "Ha ha ha! Ya ampun, kamu benar-benar anak kecil yang ingin tahu.",
  ui_story_32040401_81_dialog_content = "Bahkan, Anda sangat mengingatkan saya pada seseorang yang saya kenal ...",
  ui_story_32040401_82_dialog_content = "Saya punya satu hal terakhir yang ingin saya bagikan dengan Anda, Nak. Anda bebas untuk mempercayai kata-kata saya atau tidak, selama Anda memikirkannya.",
  ui_story_32040401_83_dialog_content = "Cara bicara Anda yang jujur dan terus terang mungkin memberi kesan kepada orang lain bahwa Anda terlalu blak-blakan atau bahkan tidak dewasa.",
  ui_story_32040401_84_dialog_content = "Tapi saya tahu bukan itu masalahnya. Anda jauh lebih berhati-hati dan perhatian daripada banyak orang dewasa, dan Anda memiliki sesuatu yang penting yang ingin Anda lindungi.",
  ui_story_32040401_85_dialog_content = "Ini, pada gilirannya, adalah alasan mengapa Anda tidak menurunkan kewaspadaan Anda dengan mudah.",
  ui_story_32040401_86_dialog_content = "Sifat Anda yang berhati-hati dan protektif adalah akar dari ketidaksopanan Anda.",
  ui_story_32040401_87_dialog_content = "Tetap saja, bahkan seseorang seperti Anda membutuhkan orang kepercayaan, seseorang yang dengannya Anda dapat berbicara dengan bebas tentang kekhawatiran Anda tanpa takut disesatkan.",
  ui_story_32040401_88_dialog_content = "Jika tidak, kekhawatiran yang sama akan terus menumpuk, dan akhirnya mengubah Anda menjadi orang yang berpandangan pendek dan bahkan bermusuhan.",
  ui_story_32040401_89_dialog_content = "Mungkin perlu waktu sebelum Anda menemukan orang kepercayaan seperti ini. Sampai saat itu, ingatlah kekurangan Anda, dan jangan biarkan mereka menguasai Anda.",
  ui_story_32040401_90_dialog_content = "...",
  ui_story_32040401_91_dialog_content = "Maaf... Apakah itu terlalu rumit untukmu?",
  ui_story_32040401_92_dialog_content = "T-Tidak sama sekali! Saya mengerti!",
  ui_story_32040401_93_dialog_content = "Meskipun beberapa kata agak sulit untuk dipahami... Saya tetap berpikir Anda benar!",
  ui_story_32040401_94_dialog_content = "J-Jadi tidak apa-apa jika... jika kita menjadi teman? Maukah Anda mendengarkan saya dan mencegah saya tersesat?",
  ui_story_32040401_95_dialog_content = "Aku?",
  ui_story_32040401_96_dialog_content = "Iya kamu! Anda adalah orang pertama yang memahami saya dengan sangat baik!",
  ui_story_32040401_97_dialog_content = "Saya... Jika Anda tidak keberatan, maka saya akan merasa terhormat.",
  ui_story_32040401_98_dialog_content = "Hore!!!",
  ui_story_32040401_99_dialog_content = "Bantuan saya... untuk membimbing yang lain?",
  ui_story_32040401_100_dialog_content = "Anda tidak diharuskan minum teh dengan istri bangsawan lainnya jika Anda tidak ingin melakukannya, Joshua.",
  ui_story_32040401_101_dialog_content = "Gubernur baru akan segera dipilih. Agar Anda menang dan membangun prestise Anda, saya harus memainkan peran sebagai istri bangsawan yang sempurna.",
  ui_story_32040401_102_dialog_content = "Sekarang bukan waktunya untuk melakukan apa yang saya inginkan.",
  ui_story_32040401_103_dialog_content = "Tetapi Joshua, apa yang akan berubah jika kita menjadi penguasa Lumopolis berikutnya dengan memenuhi keinginan para bangsawan jompo itu?",
  ui_story_32040401_104_dialog_content = "Kami tidak lebih dari boneka bangsawan, dalam hal itu.",
  ui_story_32040401_105_dialog_content = "Bagus, Daniel, tapi pendukung ayahmu sudah memihak kita.",
  ui_story_32040401_106_dialog_content = "Orang-orang sentris itu tidak peduli tentang politik, tetapi jika kita tidak meminta bantuan mereka, apa peluang kita untuk menang?!",
  ui_story_32040401_107_dialog_content = "Saya mendapat kesan bahwa Anda memainkan peran sebagai istri bangsawan yang sempurna. Mengapa Anda menunjukkan sisi diri Anda yang begitu bermusuhan kepada saya lagi?",
  ui_story_32040401_108_dialog_content = "Maafkan aku, aku hanya...",
  ui_story_32040401_109_dialog_content = "Saya tahu Anda khawatir tentang pemilu.",
  ui_story_32040401_110_dialog_content = "Dan dibandingkan saat kita pertama kali bertemu, kamu telah menjadi orang yang jauh lebih baik dan lembut... Seseorang yang juga lebih banyak tersenyum.",
  ui_story_32040401_111_dialog_content = "Itulah sebabnya saya tidak ingin Anda kembali menjadi diri Anda yang dulu: seseorang yang harus memakai penyamaran setiap saat demi mencapai tujuan yang jauh.",
  ui_story_32040401_112_dialog_content = "Aku... Aku hanya tidak tahu bagaimana melanjutkannya, terutama ketika para wanita bangsawan yang tolol itu tertawa dan mengejek orang-orang di Lumopolis Bawah.",
  ui_story_32040401_113_dialog_content = "Tetapi saya juga tidak ingin kehilangan dukungan mereka atas hal ini.",
  ui_story_32040401_114_dialog_content = "Hahaha... Saya mengerti sepenuhnya. Tidak seorang pun dari bangsawan itu yang berpikir bahwa saya dapat menempa jalan saya sendiri.",
  ui_story_32040401_115_dialog_content = "Apa yang kami lakukan saat ini adalah menjelajahi arah baru, sehingga kami dapat menjadi layak untuk membimbing orang lain menuju masa depan yang lebih baik. Karena itu, kami tidak memiliki siapa pun untuk menuntun kami ke jalan yang terbentang di depan kami.",
  ui_story_32040401_116_dialog_content = "Tapi paling tidak, kita akan memiliki satu sama lain.",
  ui_story_32040401_117_dialog_content = "Kita mungkin tidak memiliki jawaban yang tepat untuk satu sama lain setiap saat, tetapi kita dapat berbagi beban kita satu sama lain, dan menjaga diri agar tidak tersesat.",
  ui_story_32040401_118_dialog_content = "Kamu benar. Jalan menuju masa depan ideal kita tidak akan mudah dilalui... Tapi setidaknya, aku akan selalu memiliki rekan yang dapat dipercaya untuk diandalkan.",
  ui_story_32040401_119_dialog_content = "Sigh... Di saat-saat seperti inilah kau harus menyebut kami sebagai suami dan istri, atau paling tidak pasangan...",
  ui_story_32040401_120_dialog_content = "Itu dia, Nona Joshua! Aku sudah mencarimu kemana-mana!",
  ui_story_32040401_121_dialog_content = "Oh! Maaf, PlayerName, saya pasti tersesat.",
  ui_story_32040401_122_dialog_content = "Aku lega melihatmu baik-baik saja. Mari kita kembali ke Soroz, oke?",
  ui_story_32040401_123_dialog_content = "PlayerName... May Saya mengajukan pertanyaan?",
  ui_story_32040401_124_dialog_content = "Hah? Tentu.",
  ui_story_32040401_125_dialog_content = "Anda berteman dengan Carleen dan Veronica—maksudku, Mia... Ya?",
  ui_story_32040401_126_dialog_content = "Bisakah Anda memberi tahu saya bagaimana keadaan mereka berdua akhir-akhir ini?",
  ui_story_32040401_127_dialog_content = "Sebagai orang tua mereka, apakah menurut Anda Daniel dan saya... Berhasil membesarkan mereka?",
  ui_story_32040401_128_option_content = "Tentu saja! Anda adalah orang yang sangat baik.",
  ui_story_32040401_129_dialog_content = "Tentu saja kalian berdua melakukannya! Yang mulia Schwartz adalah orang yang bermartabat dan cerdas, dan Anda adalah salah satu orang paling baik dan paling lembut yang pernah saya temui.",
  ui_story_32040401_130_dialog_content = "aku yakin Mia Dan Carleen belajar banyak dari kalian berdua!",
  ui_story_32040401_131_dialog_content = "Aku mengerti... Terima kasih.",
  ui_story_32040401_132_option_content = "Saya tidak tahu, tapi saya yakin Anda melakukan yang terbaik.",
  ui_story_32040401_133_dialog_content = "Aku, uh... aku tidak Mia atau Carleen, jadi saya benar-benar tidak punya hak untuk menilai asuhan mereka, Anda tahu?",
  ui_story_32040401_134_dialog_content = "Sangat benar, ya.",
  ui_story_32040401_135_dialog_content = "Tetapi ketika saya melihat apa yang Anda dan Tuhan Schwartz telah melalui, saya pikir saya mungkin punya ide.",
  ui_story_32040401_136_dialog_content = "Kalian berdua selalu bersedia berjuang demi keluarga dan cita-cita kalian... Yang pasti mereka pelajari dari kalian.",
  ui_story_32040401_137_dialog_content = "Terima kasih, anakku sayang. Penegasan Anda lebih berarti bagi saya daripada sanjungan kosong mana pun yang biasa saya dengar. Dari lubuk hati saya, terima kasih.",
  ui_story_32040401_138_dialog_content = "K-Kamu tidak harus begitu sopan! Aku hanya mengatakan apa yang ada di pikiranku, itu saja!",
  ui_story_32040401_139_dialog_content = "Sangat baik. Mari kita ubah topik pembicaraan menjadi sesuatu yang lebih ceria.",
  ui_story_32040401_140_dialog_content = "Mengapa kita tidak membicarakan petualangan terbaru kita dalam perjalanan kembali ke Colossus?",
  ui_story_32040401_141_dialog_content = "Lagi pula, saya tidak lebih dari seorang musafir soliter sekarang. Yang saya tawarkan hanyalah pengalaman saya dari seluruh dunia."
}
return config
